import{_ as o,a0 as n,w as p,s as d,ao as l,I as r,x as a,a1 as t,A as s}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const S=JSON.parse('{"title":"使用 Fedora ARM 服務器來做 3-2-1 備份計劃 | LCTT x X-CMD","titleTemplate":false,"description":"使用 Fedora ARM 服務器來做 3-2-1 備份計劃 | LCTT (202204) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"使用 Fedora ARM 服務器來做 3-2-1 備份計劃 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"使用 Fedora ARM 服務器來做 3-2-1 備份計劃 | LCTT (202204) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202204/20220415 3-2-1 Backup plan with Fedora ARM server","title":"使用 Fedora ARM 服務器來做 3-2-1 備份計劃","tag":"202204","desc":""},"relativePath":"202204/20220415 3-2-1 Backup plan with Fedora ARM server.md","filePath":"[post].md"}'),h={name:"202204/20220415 3-2-1 Backup plan with Fedora ARM server.md"};function u(g,e,f,b,k,c){const i=n("Link");return p(),d("div",null,[e[43]||(e[43]=l('<h1 id="使用-fedora-arm-服務器來做-3-2-1-備份計劃" tabindex="-1">使用 Fedora ARM 服務器來做 3-2-1 備份計劃 <a class="header-anchor" href="#使用-fedora-arm-服務器來做-3-2-1-備份計劃" aria-label="Permalink to “使用 Fedora ARM 服務器來做 3-2-1 備份計劃”">​</a></h1><p><img src="https://fedoramagazine.org/wp-content/uploads/2022/04/3-2-1_backup-816x345.jpg" alt=""></p><p>Fedora 服務器版操作系統可以運行在類似樹莓派的單板計算機（SBC）上。這篇文章針對的用户是想要充分利用實體服務器系統，並使用類似 Cockpit 的內置工具進行數據備份和個人數據的恢復。這裏描述了備份的 3 個階段。</p><h3 id="必要的準備" tabindex="-1">必要的準備 <a class="header-anchor" href="#必要的準備" aria-label="Permalink to “必要的準備”">​</a></h3><p>想要使用本指南，你所需要的是一個運行着的 Fedora Linux 工作站和以下的項目：</p>',5)),r("ul",null,[r("li",null,[e[2]||(e[2]=a("你應該閲讀、理解和實踐 Fedora 文檔中 ",-1)),t(i,{href:"https://docs.fedoraproject.org/en-US/fedora-server/server-installation-sbc/"},{default:s(()=>[...e[0]||(e[0]=[a("服務器安裝",-1)])]),_:1}),e[3]||(e[3]=a(" 和 ",-1)),t(i,{href:"https://docs.fedoraproject.org/en-US/fedora-server/sysadmin-postinstall/"},{default:s(()=>[...e[1]||(e[1]=[a("管理",-1)])]),_:1}),e[4]||(e[4]=a(" 的要求",-1))]),r("li",null,[e[6]||(e[6]=a("一塊用來測試 Fedora Linux 的 SBC（單板計算機）。在這裏查看 ",-1)),t(i,{href:"https://docs.fedoraproject.org/en-US/quick-docs/raspberry-pi/"},{default:s(()=>[...e[5]||(e[5]=[a("硬件需求",-1)])]),_:1})]),r("li",null,[t(i,{href:"https://arm.fedoraproject.org/"},{default:s(()=>[...e[7]||(e[7]=[a("Fedora ARM",-1)])]),_:1}),e[9]||(e[9]=a()),t(i,{href:"https://arm.fedoraproject.org/"},{default:s(()=>[...e[8]||(e[8]=[a("服務器",-1)])]),_:1}),e[10]||(e[10]=a(" 原始鏡像 & ARM 鏡像安裝器",-1))]),e[11]||(e[11]=r("li",null,"SD 存儲卡（64 GB / Class 10）和 SSD 設備兩選一",-1)),e[12]||(e[12]=r("li",null,"以太網 / DHCP 預留 IP 地址或者靜態 IP 地址",-1)),e[13]||(e[13]=r("li",null,"提供了 ssh 密鑰的 Linux 客户端工作站",-1)),e[14]||(e[14]=r("li",null,"選擇雲存儲服務",-1)),e[15]||(e[15]=r("li",null,"有額外可用的 Linux 工作站",-1))]),e[44]||(e[44]=l('<p>對於這套環境，在寫這篇文章的時候，由於成本和可用性的原因，我選擇樹莓派 3B+/4B+ （其中一個用來熱切換）。當使用 Cockpit 遠程連接樹莓派服務器時，你可以將樹莓派放到路由器附近以便設置。</p><h3 id="加強服務器的安全" tabindex="-1">加強服務器的安全 <a class="header-anchor" href="#加強服務器的安全" aria-label="Permalink to “加強服務器的安全”">​</a></h3><p>在 SBC 完成服務器的安裝和管理後，用 firewalld 加強服務器的安全是一個好的做法。</p><p>連接存儲設備到服務器之前，一旦服務器在線你必須設置好防火牆。firewalld 是基於區域的防火牆。在依照 Fedora 文檔完成安裝和管理指南之後，創建一個名為 <code>FedoraServer</code> 的預定義區域。</p><h4 id="firewalld-裏的富規則" tabindex="-1">firewalld 裏的富規則 <a class="header-anchor" href="#firewalld-裏的富規則" aria-label="Permalink to “firewalld 裏的富規則”">​</a></h4><p><ruby>富規則<rt>rich rule</rt></ruby>用來阻止或者允許一個特定的 IP 地址或者地址段。下面這條規則只從（客户端工作站）註冊的 IP 地址接受 SSH 連接，並斷開其它的連接。在 Cockpit 終端或者客户端工作站終端運行命令是通過 ssh 來連接到服務器的。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>firewall-cmd --add-rich-rule=&#39;rule family=ipv4 source address=&lt;registered_ip_address&gt;/24 service name=ssh log prefix=&quot;SSH Logs&quot; level=&quot;notice&quot; accept&#39;</span></span></code></pre></div><h4 id="拒絕所有主機的-ping-請求" tabindex="-1">拒絕所有主機的 ping 請求 <a class="header-anchor" href="#拒絕所有主機的-ping-請求" aria-label="Permalink to “拒絕所有主機的 ping 請求”">​</a></h4><p>使用這個命令來設置 icmp 拒絕，並且不允許 ping 請求：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>firewall-cmd --add-rich-rule=&#39;rule protocol value=icmp reject&#39;</span></span></code></pre></div><p>要進行其它防火牆控制，比如管理端口和區域，請查閲以下鏈接。請注意錯配防火牆可能會使安全出現漏洞受到攻擊。</p>',11)),r("blockquote",null,[r("p",null,[r("strong",null,[t(i,{href:"https://fedoramagazine.org/managing-network-interfaces-and-firewalld-in-cockpit/"},{default:s(()=>[...e[16]||(e[16]=[a("在 Cockpit 中管理防火牆",-1)])]),_:1})])])]),r("blockquote",null,[r("p",null,[r("strong",null,[t(i,{href:"https://www.redhat.com/sysadmin/firewalld-rules-and-scenarios"},{default:s(()=>[...e[17]||(e[17]=[a("firewalld 規則",-1)])]),_:1})])])]),e[45]||(e[45]=l('<h3 id="配置文件服務器的存儲" tabindex="-1">配置文件服務器的存儲 <a class="header-anchor" href="#配置文件服務器的存儲" aria-label="Permalink to “配置文件服務器的存儲”">​</a></h3><p>下一步是連接存儲設備到 SBC，然後使用 Cockpit 對新插入的存儲設備進行分區。使用 Cockpit 的圖形化服務器管理界面，管理一個家庭實驗室（可以是一個或者多個服務器）比之前更加簡單。Fedora Linux 服務器標準提供了 Cockpit。</p><p>在這個階段，一個通過 SBC 的 USB 插口接電的 SSD 設備無需額外電源供給就可以工作。</p><ul><li>將存儲設備連接到 SBC 的 USB 接口</li><li>運行之後（按上面的“必要的準備”所設置的那樣），然後在你的客户端工作站瀏覽器上訪問 <strong>機器的 IP 地址:9090</strong></li><li>登錄進 Cockpit 之後，點擊 Cockpit 頁面頂部的“<ruby>打開管理訪問權限<rt>Turn on administrative access</rt></ruby>”</li><li>點擊左邊面板的 “<ruby>存儲<rt>Storage</rt></ruby>” 按鈕</li><li>選擇下面顯示的 “<ruby>驅動器<rt>Drives</rt></ruby>”，然後分區並格式化一個空白的存儲設備 <img src="https://fedoramagazine.org/wp-content/uploads/2022/03/Screenshot-from-2022-03-29-22-05-00b-1024x576.png" alt="Cockpit Storage management"></li><li>在選定的存儲設備這個界面上，創建一個新的分區表或者格式化並創建新的分區。當初始化磁盤的時候，在 “<ruby>Partitioning<rt>分區</rt></ruby>” 類型選項上，選擇 “GPT 分區表”</li><li>選擇一個文件系統類型，這裏選擇 “EXT4” 。這對於一個限制 I/O 能力（比如 USB 2.0 接口）和限制帶寬（小於 200MB/s）的設備是適合的 <img src="https://fedoramagazine.org/wp-content/uploads/2022/03/Screenshot-from-2022-03-29-22-03-36a.png" alt="Create a partition in Cockpit"></li><li>要在設備上創建單個佔據整個存儲空間的分區，指定它的掛載點，比如 <code>/media</code> 然後點擊 “<ruby>確定<rt>Ok</rt></ruby>” 。</li><li>點擊 “<ruby>Create partition<rt>創建分區</rt></ruby>”，創建一個掛載點為 <code>/media</code> 的新分區。</li></ul><h3 id="創建備份和恢復備份" tabindex="-1">創建備份和恢復備份 <a class="header-anchor" href="#創建備份和恢復備份" aria-label="Permalink to “創建備份和恢復備份”">​</a></h3><p>備份很少是一刀切的。這裏有一些選擇比如數據備份在哪裏，備份數據的步驟，驗證一些自動化，並確定怎樣來恢復備份了的數據。</p><p><img src="https://fedoramagazine.org/wp-content/uploads/2022/04/Backups3-1-1024x525.jpg" alt="Backup workflow – version 1.0"></p><h4 id="備份-1-用-rsync-從客户端遠程同步到文件服務器-樹莓派" tabindex="-1">備份 1. 用 rsync 從客户端遠程同步到文件服務器（樹莓派） <a class="header-anchor" href="#備份-1-用-rsync-從客户端遠程同步到文件服務器-樹莓派" aria-label="Permalink to “備份 1. 用 rsync 從客户端遠程同步到文件服務器（樹莓派）”">​</a></h4><p>這個傳輸用到的命令是：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>rsync -azP ~/source syncuser@host1:/destination</span></span></code></pre></div><p>參數:</p><ul><li><code>-a</code>/<code>--archive</code>：歸檔</li><li><code>-z</code>/<code>--compress</code>：壓縮</li><li><code>-P</code>/<code>--progress</code>：顯示進度</li></ul><p>要使用更多的選項運行 <code>rsync</code>，可以設置以下的選項：</p><ul><li><code>--inplace</code>：直接替換來更新目標文檔</li><li><code>--append</code>：追加數據到較短的文檔中</li></ul><p>在將文檔備份到存儲空間之前，源端文檔的文件重複消除和壓縮是減少備份數據容量最有效的方式。</p><p>每天工作結束，我會手動運行這個。一旦我設置了雲備份工作流，自動化腳本是一個優勢。</p>',16)),r("p",null,[e[19]||(e[19]=a("關於 ",-1)),e[20]||(e[20]=r("code",null,"rsync",-1)),e[21]||(e[21]=a(" 的詳細信息，請在 ",-1)),t(i,{href:"https://fedoramagazine.org/copying-large-files-with-rsync-and-some-misconceptions/"},{default:s(()=>[...e[18]||(e[18]=[a("這裏",-1)])]),_:1}),e[22]||(e[22]=a(" 訪問 Fedora 雜誌的文章。",-1))]),e[46]||(e[46]=l('<h4 id="備份-2-使用-rysnc-從文件服務器遠程同步到主要的雲存儲上" tabindex="-1">備份 2. 使用 rysnc 從文件服務器遠程同步到主要的雲存儲上 <a class="header-anchor" href="#備份-2-使用-rysnc-從文件服務器遠程同步到主要的雲存儲上" aria-label="Permalink to “備份 2. 使用 rysnc 從文件服務器遠程同步到主要的雲存儲上”">​</a></h4><p>選擇雲存儲是考慮的因素；</p><ul><li>成本：上傳、存儲空間和下載費用</li><li>支持 <code>rsync</code>、<code>sftp</code></li><li>數據冗餘（RAID 10 或者運行中的數據中心冗餘計劃）</li><li>快照</li></ul>',3)),r("p",null,[e[24]||(e[24]=a("符合這些雲存儲標準之一的就是 Hetzner 託管的 Nextcloud– ",-1)),t(i,{href:"https://docs.hetzner.com/robot/storage-box/"},{default:s(()=>[...e[23]||(e[23]=[a("存儲盒子",-1)])]),_:1}),e[25]||(e[25]=a("。你不會受到供應商限制，可以自由切換而沒有退出懲罰。",-1))]),e[47]||(e[47]=l(`<h5 id="在文件服務器上生成-ssh-密鑰並創建授權密鑰文件" tabindex="-1">在文件服務器上生成 SSH 密鑰並創建授權密鑰文件 <a class="header-anchor" href="#在文件服務器上生成-ssh-密鑰並創建授權密鑰文件" aria-label="Permalink to “在文件服務器上生成 SSH 密鑰並創建授權密鑰文件”">​</a></h5><p>使用 <code>ssh-keygen</code> 命令為文件服務器和雲存儲生成一對新的 SSH 密鑰對。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>ssh-keygen</span></span>
<span class="line"><span>Generating public/private rsa key pair.</span></span>
<span class="line"><span>Enter file in which to save the key . . .</span></span></code></pre></div><p>插入要求的 SSH 公鑰到新的本地授權密鑰文件中。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>cat .ssh/id_rsa.pub &gt;&gt; storagebox_authorized_keys</span></span></code></pre></div><h5 id="傳輸密鑰文件到雲存儲" tabindex="-1">傳輸密鑰文件到雲存儲 <a class="header-anchor" href="#傳輸密鑰文件到雲存儲" aria-label="Permalink to “傳輸密鑰文件到雲存儲”">​</a></h5><p>下一步就是上傳生成了的授權密鑰文件到存儲盒子。要做這些，先用 700 權限創建 <code>.ssh</code> 目錄，然後用 SSH 公鑰創建授權文件並賦予 600 權限。運行以下命令。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>echo -e &quot;mkdir .ssh \\n chmod 700 .ssh \\n put storagebox_authorized_keys .ssh/authorized_keys \\n chmod 600 .ssh/authorized_keys&quot; | sftp &lt;username&gt;@&lt;username&gt;.your-storagebox.de</span></span></code></pre></div><h5 id="通過-ssh-使用-rsync" tabindex="-1">通過 ssh 使用 rsync <a class="header-anchor" href="#通過-ssh-使用-rsync" aria-label="Permalink to “通過 ssh 使用 rsync”">​</a></h5><p>使用 <code>rsync</code> 同步你的文件目錄當前狀態到存儲盒子。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>rsync --progress -e &#39;ssh -p23&#39; --recursive &lt;local_directory&gt; &lt;username&gt;@&lt;username&gt;.your-storagebox.de:&lt;target_directory&gt;</span></span></code></pre></div><p>這個過程被叫做推送操作，因為它 “推送” 本地系統的一個目錄到一個遠程的系統中去。</p><h5 id="從雲存儲中恢復目錄" tabindex="-1">從雲存儲中恢復目錄 <a class="header-anchor" href="#從雲存儲中恢復目錄" aria-label="Permalink to “從雲存儲中恢復目錄”">​</a></h5><p>要從存儲盒子恢復目錄，轉換到這個目錄：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>rsync --progress -e &#39;ssh -p23&#39; --recursive &lt;username&gt;@&lt;username&gt;.your-storagebox.de:&lt;remote_directory&gt; &lt;local_directory&gt;</span></span></code></pre></div><h4 id="備份-3-客户端備份到第二個雲儲存" tabindex="-1">備份 3. 客户端備份到第二個雲儲存 <a class="header-anchor" href="#備份-3-客户端備份到第二個雲儲存" aria-label="Permalink to “備份 3. 客户端備份到第二個雲儲存”">​</a></h4>`,16)),r("p",null,[t(i,{href:"https://fedoramagazine.org/easy-backups-with-deja-dup/"},{default:s(()=>[...e[26]||(e[26]=[a("Deja Dup",-1)])]),_:1}),e[27]||(e[27]=a(" 是 Fedora 軟件倉庫中為 Fedora 工作站提供快速備份解決方案的工具。它擁有 GPG 加密、計劃任務、文件包含（哪個目錄要備份）等功能。",-1))]),e[48]||(e[48]=l('<p><img src="https://fedoramagazine.org/wp-content/uploads/2022/03/Screenshot-from-2022-03-29-22-47-30.png" alt="Backing up to the secondary cloud"></p><p><img src="https://fedoramagazine.org/wp-content/uploads/2022/03/Screenshot-from-2022-03-29-22-41-57.png" alt="Restoring files from cloud storage"></p><h3 id="歸檔個人數據" tabindex="-1">歸檔個人數據 <a class="header-anchor" href="#歸檔個人數據" aria-label="Permalink to “歸檔個人數據”">​</a></h3><p>不是所有數據都需要 3-2-1 備份策略。這就是個人數據共享。我將一台擁有 1TB 硬盤的筆記本作為我個人數據的檔案（家庭照片）。</p><p>轉到設置中的 “<ruby>共享<rt>Sharing</rt></ruby>” （在我的例子中是 GNOME 文件管理器）並切換滑塊以啓用共享。</p><p><img src="https://fedoramagazine.org/wp-content/uploads/2022/04/Screenshot-from-2022-04-14-20-48-49-1024x733.png" alt=""></p><p>打開 “<ruby>文件共享<rt>file sharing</rt></ruby>”，“<ruby>網絡<rt>Networks</rt></ruby>” 和 “<ruby>需要的密碼<rt>Required password</rt></ruby>”，允許你使用 WebDAV 協議在你的本地網絡上分享你的公共文件夾給其它的工作站。</p><p><img src="https://fedoramagazine.org/wp-content/uploads/2022/04/Screenshot-from-2022-04-14-20-51-18st.png" alt=""></p><h3 id="準備回滾選項" tabindex="-1">準備回滾選項 <a class="header-anchor" href="#準備回滾選項" aria-label="Permalink to “準備回滾選項”">​</a></h3><p>未測試的備份並不比完全沒有備份好。我在家庭實驗室環境中使用 “熱切換” 方法來避免像頻繁的斷電或者液體損壞的情況發生。然而，我的建議方案遠沒有達到災難恢復計劃或企業 IT 中的自動故障修復。</p><ul><li>定期運行文件恢復操作</li><li>備份 ssh/GPG 密鑰到一個額外的存儲設備中</li><li>複製一個 Fedora ARM 服務器的原始鏡像到一個 SD 卡中</li><li>在主雲存儲中保持全備份的快照</li><li>自動化備份過程最小化減少人為錯誤或者疏忽</li></ul><h3 id="使用-cockpit-追蹤活動並解決問題" tabindex="-1">使用 Cockpit 追蹤活動並解決問題 <a class="header-anchor" href="#使用-cockpit-追蹤活動並解決問題" aria-label="Permalink to “使用 Cockpit 追蹤活動並解決問題”">​</a></h3><p>當你的項目在成長時，你所管理的服務器數量也在增長。在 Cockpit 中追蹤活動和警告可以減輕你的管理負擔。你可以使用 Cockpit 的圖形化界面的三種方法來歸檔這些。</p><h4 id="selinux-菜單" tabindex="-1">SELinux 菜單 <a class="header-anchor" href="#selinux-菜單" aria-label="Permalink to “SELinux 菜單”">​</a></h4><p>怎樣診斷網絡問題，找到日誌並在 Cockpit 中解決問題：</p><ul><li>去 SELinux 中檢查日誌</li><li>檢查“<ruby>解決方案詳細信息<rt>solution details</rt></ruby>”</li><li>當必要時，選擇 “<ruby>應用這個方案<rt>Apply this solution</rt></ruby>”</li><li>如果必要，查看自動化腳本並運行它</li></ul><p><img src="https://fedoramagazine.org/wp-content/uploads/2022/04/Screenshot-from-2022-04-02-11-24-30b-1024x441.png" alt="SELinux logs"></p><h4 id="網絡或者存儲日誌" tabindex="-1">網絡或者存儲日誌 <a class="header-anchor" href="#網絡或者存儲日誌" aria-label="Permalink to “網絡或者存儲日誌”">​</a></h4><p>服務器日誌會跟蹤 CPU 負載、內存使用、網絡活動、存儲性能和系統日誌關聯的詳細指標。日誌會組織在網絡面板或者存儲面板裏顯示。</p><p><img src="https://fedoramagazine.org/wp-content/uploads/2022/04/Screenshot-from-2022-04-04-21-47-06SL-1024x259.png" alt="Storage logs in Cockpit"></p><h4 id="軟件更新" tabindex="-1">軟件更新 <a class="header-anchor" href="#軟件更新" aria-label="Permalink to “軟件更新”">​</a></h4><p>在預設的時間和頻率下，Cockpit 可以幫助進行安全更新。當你需要時，你可以運行所有的更新。</p><p><img src="https://fedoramagazine.org/wp-content/uploads/2022/04/Screenshot-from-2022-04-04-21-35-42b.png" alt="Software updates"></p><p>恭喜你在 Fedora ARM 服務器版本上搭建了一個文件/備份服務器。</p><hr>',25)),r("p",null,[e[29]||(e[29]=a("via: ",-1)),t(i,{href:"https://fedoramagazine.org/3-2-1-backup-plan-with-fedora-arm-server/"},{default:s(()=>[...e[28]||(e[28]=[a("https://fedoramagazine.org/3-2-1-backup-plan-with-fedora-arm-server/",-1)])]),_:1})]),r("p",null,[e[34]||(e[34]=a("作者：",-1)),t(i,{href:"https://fedoramagazine.org/author/hankuoffroad/"},{default:s(()=>[...e[30]||(e[30]=[a("Hanku Lee",-1)])]),_:1}),e[35]||(e[35]=a(" 選題：",-1)),t(i,{href:"https://github.com/lujun9972"},{default:s(()=>[...e[31]||(e[31]=[a("lujun9972",-1)])]),_:1}),e[36]||(e[36]=a(" 譯者：",-1)),t(i,{href:"https://github.com/hwlife"},{default:s(()=>[...e[32]||(e[32]=[a("hwlife",-1)])]),_:1}),e[37]||(e[37]=a(" 校對：",-1)),t(i,{href:"https://github.com/wxy"},{default:s(()=>[...e[33]||(e[33]=[a("wxy",-1)])]),_:1})]),r("p",null,[e[40]||(e[40]=a("本文由 ",-1)),t(i,{href:"https://github.com/LCTT/TranslateProject"},{default:s(()=>[...e[38]||(e[38]=[a("LCTT",-1)])]),_:1}),e[41]||(e[41]=a(" 原創編譯，",-1)),t(i,{href:"https://linux.cn/"},{default:s(()=>[...e[39]||(e[39]=[a("Linux中國",-1)])]),_:1}),e[42]||(e[42]=a(" 榮譽推出",-1))])])}const C=o(h,[["render",u]]);export{S as __pageData,C as default};
